"""Stage 5 (CPU): auto-generated LaTeX macros for the revised Section 6.3,
following the paper's macro-synchronisation convention
(generated/results_6x.tex with \\providecommand fallbacks).

Output: generated/results_63eps.tex
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

import numpy as np
import yaml

EPS_NAMES = {0.1: "EpsTen", 0.05: "EpsFive", 0.02: "EpsTwo",
             0.01: "EpsOne", 0.0: "EpsZero"}
LAM_NAMES = {0.4: "LamFour", 0.6: "LamSix", 0.8: "LamEight"}


def sci(v: float, digits: int = 1) -> str:
    if v == 0:
        return "0"
    exp = int(np.floor(np.log10(abs(v))))
    if -2 <= exp <= 2:
        s = f"{v:.{max(digits + 1 - exp, 0)}f}"
        return s.rstrip("0").rstrip(".") if "." in s else s
    mant = v / 10 ** exp
    return rf"{mant:.{digits}f}\times 10^{{{exp}}}"


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--config", default="configs/relay_eps.yaml")
    ap.add_argument("--root", default="results/relay_eps")
    ap.add_argument("--out", default="results/aggregated/results_63eps.tex")
    args = ap.parse_args()
    cfg = yaml.safe_load(Path(args.config).read_text())
    root = Path(args.root)
    res = json.loads((root / "eval_summary.json").read_text())
    lam0, eps0 = cfg["lam_baseline"], cfg["eps_baseline"]

    lines = ["% Auto-generated by stage_macros.py -- do not edit by hand.",
             "% Revised Section 6.3 (dead-zone relay Phi_eps)."]

    def put(name: str, value: str) -> None:
        lines.append(rf"\providecommand{{\{name}}}{{{value}}}")

    # torsion witness threshold
    tor = np.load(root / "reference" / "torsion.npz")
    put("RelayVOneInf", f"{float(tor['v1_inf']):.4f}")
    put("RelayWitnessThreshold", f"{lam0 * float(tor['v1_inf']):.4f}")

    # reference extinction times
    for lam, lname in LAM_NAMES.items():
        p = root / "reference" / f"ref_lam{lam:g}.npz"
        if p.exists():
            put(f"RelayRefTstar{lname}", f"{float(np.load(p)['t_star']):.4f}")

    # eps-sweep residuals (median over seeds, front sampler, lam baseline)
    for e, ename in EPS_NAMES.items():
        vals_m = [r["residual"]["mean"] for r in res
                  if r["lam"] == lam0 and r["eps"] == e and r["sampler"] == "front"]
        vals_x = [r["residual"]["max"] for r in res
                  if r["lam"] == lam0 and r["eps"] == e and r["sampler"] == "front"]
        if vals_m:
            put(f"RelayResMean{ename}", sci(float(np.median(vals_m))))
            put(f"RelayResMax{ename}", sci(float(np.median(vals_x))))

    # baseline run details (eps0, lam0)
    base = [r for r in res if r["lam"] == lam0 and r["eps"] == eps0
            and r["sampler"] == "front"]
    if base:
        put("RelayBaselineValLoss",
            sci(float(np.median([r["final_val_mean"] for r in base]))))
        put("RelayBaselineNormDisc",
            f"{100 * float(np.median([r['norm_discrepancy_pre'] for r in base])):.2f}\\%")
        viol = sum(r["violations"] for r in base)
        tot = sum(r["cloud_size"] for r in base)
        put("RelayBaselineViolations", f"{viol}/{tot}")
        tb = [r["t_band"] for r in base if r["t_band"] is not None]
        tbp = [r["t_band_persistent"] for r in base if r["t_band_persistent"] is not None]
        if tb:
            put("RelayBaselineTBandMedian", f"{float(np.median(tb)):.4f}")
            put("RelayBaselineTBandRange",
                f"[{min(tb):.4f},\\,{max(tb):.4f}]")
        put("RelayBaselineTBandPersistentCount", f"{len(tbp)}/{len(base)}")
        # residual strata (referee request)
        for stratum in ("pre", "front", "post"):
            v = [r["residual"][f"mean_{stratum}"] for r in base
                 if r["residual"][f"mean_{stratum}"] is not None]
            if v:
                put(f"RelayBaselineResMean{stratum.capitalize()}",
                    sci(float(np.median(v))))

    # band-time monotonicity across lam at eps0
    med_tb = {}
    for lam, lname in LAM_NAMES.items():
        tb = [r["t_band"] for r in res
              if r["lam"] == lam and r["eps"] == eps0 and r["sampler"] == "front"
              and r["t_band"] is not None]
        if tb:
            med_tb[lam] = float(np.median(tb))
            put(f"RelayTBandMedian{lname}", f"{med_tb[lam]:.4f}")
    if len(med_tb) == 3:
        mono = med_tb[0.8] <= med_tb[0.6] <= med_tb[0.4]
        put("RelayTBandMonotone", "preserved" if mono else "violated")

    # ablation medians
    for m in ["front"] + list(cfg["ablation_samplers"]):
        v = [r["residual"]["mean"] for r in res
             if r["lam"] == lam0 and r["eps"] == eps0 and r["sampler"] == m]
        if v:
            put(f"RelayAblation{m.capitalize()}", sci(float(np.median(v))))

    outp = Path(args.out); outp.parent.mkdir(parents=True, exist_ok=True)
    outp.write_text("\n".join(lines) + "\n")
    print(f"{len(lines) - 2} macros -> {outp}")


if __name__ == "__main__":
    main()
